{
  "intent": "Why can't I use a disposable card?",
  "response": "It seems you're having trouble using your disposable card. This could be due to a few reasons. First, ensure that the card is properly activated and linked to your account. If you've recently activated the card, it might take a few minutes for the system to recognize it. Additionally, check if the card is within its expiration date. If the card is expired, it won't work. If you've lost the card, contact our customer service to request a replacement. Please try these steps and let us know if the issue persists.",
  "action_required": true,
  "tool_name": null,
  "tool_arguments": {}
}

{
  "intent": "card_not_working",
  "response": "If your ATM is not returning your card, it could be due to a few reasons. Please check if the card is properly inserted and if the card reader is functioning correctly. If the issue persists, you can contact our customer service for further assistance. Alternatively, you can try using a different ATM or a different bank's ATM.",
  "action_required": false,
  "tool_name": null,
  "tool_arguments": {}
}

